  "check_code": """"Deterministic post-state checks for the forecast corrective-action task."""

import re
import sqlite3
from datetime import date, datetime
from pathlib import Path


SCENARIO_ID = "FCST_QD_2024_BASE_001"
FORECAST_LINE_ID = "FL_QD23_PROJECT_A_031"
OWNER_DEPARTMENT_ID = "DEPTSET_QIDONG_CLINICAL_2023"
HISTORY_IDS = {"ACT_QD24_PROJ_018", "ACT_QD24_PROJ_019"}


def _connect(workspace):
    db_path = Path(workspace).parent / "system" / "fanruan_clinical_forecast" / "state.db"
    connection = sqlite3.connect(str(db_path))
    connection.row_factory = sqlite3.Row
    return connection


def _norm(value):
    return re.sub(r"[\s，,。；;：:、/／（）()\-—_]+", "", "" if value is None else str(value)).casefold()


def _parse_date(value):
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    text = str(value).strip()
    for pattern in ("%Y-%m-%d", "%Y/%m/%d", "%Y.%m.%d", "%Y年%m月%d日"):
        try:
            return datetime.strptime(text, pattern).date()
        except ValueError:
            continue
    return None


def _new_actions(connection):
    rows = connection.execute(
        """
        SELECT action_id, scenario_id, forecast_line_id, owner_department_id,
               action_type, due_date, action_status, owner_name,
               threshold_percent, exemption_basis, action_note
        FROM corrective_action
        WHERE scenario_id=? AND forecast_line_id=?
          AND action_id NOT IN (?, ?)
        ORDER BY action_id
        """,
        (SCENARIO_ID, FORECAST_LINE_ID, *sorted(HISTORY_IDS)),
    ).fetchall()
    return [dict(row) for row in rows]


def check_new_action_core(workspace):
    with _connect(workspace) as connection:
        rows = _new_actions(connection)
    if len(rows) != 1:
        return {"score": 0, "detail": f"目标预测行应恰有1条新增事项，实际为{len(rows)}条"}
    row = rows[0]
    expected = {
        "scenario_id": SCENARIO_ID,
        "forecast_line_id": FORECAST_LINE_ID,
        "owner_department_id": OWNER_DEPARTMENT_ID,
        "action_type": "PROJECT_RESCHEDULE",
        "action_status": "OPEN",
    }
    mismatches = [key for key, value in expected.items() if _norm(row.get(key)) != _norm(value)]
    if mismatches:
        return {"score": 0, "detail": "新增事项核心关联或状态不符: " + ", ".join(mismatches)}
    return {"score": 1, "detail": f"新增事项 {row['action_id']} 的情景、预测行、责任科室、类型和状态正确"}


def check_new_action_followup_fields(workspace):
    with _connect(workspace) as connection:
        rows = _new_actions(connection)
    if len(rows) != 1:
        return {"score": 0, "detail": f"无法唯一识别新增事项，实际候选{len(rows)}条"}
    row = rows[0]
    problems = []
    if _norm(row.get("owner_name")) != _norm("王敏"):
        problems.append("责任人")
    try:
        if abs(float(row.get("threshold_percent")) - 5.0) > 1e-9:
            problems.append("阈值")
    except (TypeError, ValueError):
        problems.append("阈值")
    if _parse_date(row.get("due_date")) != date(2024, 10, 15):
        problems.append("到期日")

    note = _norm(row.get("action_note"))
    semantic_groups = [
        ("项目",),
        ("结算",),
        ("时点", "节点"),
        ("跟踪", "追踪"),
        ("设备科",),
        ("财务科",),
        ("复核", "核对", "会同"),
    ]
    if any(not any(_norm(token) in note for token in group) for group in semantic_groups):
        problems.append("事项说明")
    if problems:
        return {"score": 0, "detail": "新增事项跟踪字段不符: " + ", ".join(problems)}
    return {"score": 1, "detail": "责任人、5%阈值、2024-10-15到期日及协同复核说明正确"}


def check_history_unchanged(workspace):
    expected = {
        "ACT_QD24_PROJ_018": {
            "scenario_id": SCENARIO_ID,
            "forecast_line_id": FORECAST_LINE_ID,
            "owner_department_id": OWNER_DEPARTMENT_ID,
            "action_type": "PROJECT_RESCHEDULE",
            "due_date": "2024-06-30",
            "action_status": "COMPLETED",
            "owner_name": "王敏",
            "threshold_percent": 5,
            "exemption_basis": "项目结算节点已完成，仍保留跨期差异说明",
            "action_note": "完成设备购置项目结算节点核对",
        },
        "ACT_QD24_PROJ_019": {
            "scenario_id": SCENARIO_ID,
            "forecast_line_id": FORECAST_LINE_ID,
            "owner_department_id": OWNER_DEPARTMENT_ID,
            "action_type": "PROJECT_RESCHEDULE",
            "due_date": "2024-09-30",
            "action_status": "REOPENED",
            "owner_name": "王敏",
            "threshold_percent": 5,
            "exemption_basis": None,
            "action_note": "新情景项目时点仍超预算偏差阈值，重新打开跟踪",
        },
    }
    with _connect(workspace) as connection:
        rows = connection.execute(
            "SELECT * FROM corrective_action WHERE action_id IN (?, ?)",
            tuple(sorted(HISTORY_IDS)),
        ).fetchall()
    actual = {row["action_id"]: dict(row) for row in rows}
    if set(actual) != HISTORY_IDS:
        return {"score": 0, "detail": "既有历史事项缺失"}
    for action_id, fields in expected.items():
        row = actual[action_id]
        for key, value in fields.items():
            if key == "threshold_percent":
                try:
                    same = abs(float(row[key]) - float(value)) <= 1e-9
                except (TypeError, ValueError):
                    same = False
            elif key == "due_date":
                same = _parse_date(row[key]) == _parse_date(value)
            elif value is None:
                same = row[key] is None
            else:
                same = _norm(row[key]) == _norm(value)
            if not same:
                return {"score": 0, "detail": f"历史事项 {action_id} 的 {key} 被改动"}
    return {"score": 1, "detail": "两条既有事项完整保留且业务字段未改"}


def check_mutation_scope(workspace):
    with _connect(workspace) as connection:
        total = connection.execute("SELECT COUNT(*) FROM corrective_action").fetchone()[0]
        target_total = connection.execute(
            "SELECT COUNT(*) FROM corrective_action WHERE scenario_id=? AND forecast_line_id=?",
            (SCENARIO_ID, FORECAST_LINE_ID),
        ).fetchone()[0]
    if total != 43 or target_total != 3:
        return {
            "score": 0,
            "detail": f"事项变更范围异常：全表{total}条（应43），目标行{target_total}条（应3）",
        }
    return {"score": 1, "detail": "纠偏事项仅增加1条，且落在指定项目支出预测行"}
